            Stroke = RGB(210,218,232),     StrokeBright = RGB(178,190,212),
            Text = RGB(28,34,48),          SubText = RGB(106,116,138),
            Accent = RGB(66,113,244),      AccentHover = RGB(90,132,247), OnAccent = RGB(255,255,255),
